static void add_edge(int u, int v, int *head, int *to, int *next, int *edge_count) {
    to[*edge_count] = v;
    next[*edge_count] = head[u];
    head[u] = (*edge_count)++;

    to[*edge_count] = u;
    next[*edge_count] = head[v];
    head[v] = (*edge_count)++;
}

static int bfs(int n, int *head, int *to, int *next, int start,
               int *dist, int *parent, int *queue) {
    for (int i = 0; i < n; i++) {
        dist[i] = -1;
    }

    int front = 0, back = 0;
    queue[back++] = start;
    dist[start] = 0;
    if (parent != NULL) {
        parent[start] = -1;
    }

    int farthest = start;
    while (front < back) {
        int u = queue[front++];
        if (dist[u] > dist[farthest]) {
            farthest = u;
        }

        for (int e = head[u]; e != -1; e = next[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                if (parent != NULL) {
                    parent[v] = u;
                }
                queue[back++] = v;
            }
        }
    }

    return farthest;
}

static int find_center(int n, int *head, int *to, int *next,
                       int *dist, int *parent, int *queue) {
    int endpoint_a = bfs(n, head, to, next, 0, dist, NULL, queue);
    int endpoint_b = bfs(n, head, to, next, endpoint_a, dist, parent, queue);

    int diameter = dist[endpoint_b];
    int center = endpoint_b;
    for (int i = 0; i < diameter / 2; i++) {
        center = parent[center];
    }
    return center;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) {
        return 0;
    }

    int *head1 = malloc((size_t)n * sizeof(int));
    int *to1 = malloc((size_t)2 * (n - 1) * sizeof(int));
    int *next1 = malloc((size_t)2 * (n - 1) * sizeof(int));
    int *head2 = malloc((size_t)m * sizeof(int));
    int *to2 = malloc((size_t)2 * (m - 1) * sizeof(int));
    int *next2 = malloc((size_t)2 * (m - 1) * sizeof(int));

    for (int i = 0; i < n; i++) head1[i] = -1;
    for (int i = 0; i < m; i++) head2[i] = -1;

    int edge_count = 0;
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        add_edge(a - 1, b - 1, head1, to1, next1, &edge_count);
    }

    edge_count = 0;
    for (int i = 0; i < m - 1; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        add_edge(x - 1, y - 1, head2, to2, next2, &edge_count);
    }

    int *dist1 = malloc((size_t)n * sizeof(int));
    int *parent1 = malloc((size_t)n * sizeof(int));
    int *queue1 = malloc((size_t)n * sizeof(int));
    int *dist2 = malloc((size_t)m * sizeof(int));
    int *parent2 = malloc((size_t)m * sizeof(int));
    int *queue2 = malloc((size_t)m * sizeof(int));

    int center1 = find_center(n, head1, to1, next1, dist1, parent1, queue1);
    int center2 = find_center(m, head2, to2, next2, dist2, parent2, queue2);

    printf("%d %d\n", center1 + 1, center2 + 1);

